  const preview=(a.preview||[]).map(p=>'<tr><th>'+ES(parameter(p.entity_id,p.label))+'</th><td>'+ES(value(p.actual_value))+'</td><td>'+ES(p.role==='pause_conflicting_automation'?'Plánované pozastavení jen v 03–05':p.role==='read_only_persistent_setting'?'Trvalé nastavení · pouze čtení':'Parametr ve virtuální správě')+'</td></tr>').join('');
  const sourceChoice=archive?'<select id="control-source" aria-label="Zdroj řídicího deníku" '+(this.controlLoading?'disabled':'')+'><option value="reconstruction" '+(archiveMode?'selected':'')+'>Rekonstrukce '+ES(cache.session?.provenance?.software_version||archive.software_version||'')+'</option>'+((a.session?.day===day||(a.sessions||[]).some(x=>x.day===day))?'<option value="live" '+(!archiveMode?'selected':'')+'>Původní živý záznam</option>':'')+'</select> ':'';
