  const nights=hist.map(h=>{const ev=h.models?.ev||{},b=h.models?.battery||{},sel=h.models?.selected||{};const ctrl=h.controller?.shadow_model;return '<tr><th>'+ES(h.day)+'</th><td>'+NF(h.observed_covered_s>0?h.observed_ev_kwh_ac:null,2)+'</td><td>'+energy(sel,'battery_kwh_ac')+'</td><td>'+energy(ctrl,'battery_kwh_ac')+'<small>SOC '+NF(ctrl?.covered_s>0?ctrl.soc_pct:null,1)+' % · '+NF(ctrl?.covered_s>0?ctrl.covered_s/60:null,1)+' min</small></td><td>'+energy(ev,'battery_kwh_ac')+' / '+energy(b,'battery_kwh_ac')+'</td><td>'+NF(sel.covered_s>0?sel.soc_pct:null,1)+' %</td><td>'+energy(sel,'ev_reallocated_kwh')+'</td><td>'+NF((sel.covered_s??0)/60,1)+' / 120<small>Auto '+NF(h.observed_covered_s==null?null:h.observed_covered_s/60,1)+' min · '+NF(h.sample_count,0)+' vzorků · v'+ES(h.version||'—')+'</small></td><td>'+['L1','L2','L3'].map(k=>NF(h.phase_max_measured_a?.[k])).join(' / ')+'</td></tr>';}).join('');
  const controlHTML=this.controlPanel();
