   '<div class="control"><h2>Komu dát přednost?</h2><div class="segment" role="group" aria-label="Priorita stínového nabíjení"><button data-choice="Elektromobil" aria-pressed="'+(helper==='Elektromobil')+'" class="'+(helper==='Elektromobil'?'active ev':'')+'">'+ICON('car')+'Elektromobil</button><button data-choice="Baterie SolaX" aria-pressed="'+(helper==='Baterie SolaX')+'" class="'+(helper==='Baterie SolaX'?'active bat':'')+'">'+ICON('battery')+'Baterie SolaX</button></div></div>'+
   '<div class="header-status"><span class="badge"><i></i> STÍNOVÝ AUDIT</span><small>0 povelů do zařízení · v'+ES(d.version||'0.6.2')+'</small></div></header>'+
   '<div class="notice '+(healthWarning?'warn':'')+'"><span class="status-dot"></span><strong>'+ES(health.status==='failed'?currentState:stale?'Sběr nemá čerstvá data':currentState)+'</strong><span>'+ES('Poslední úspěšný sběr '+TM(health.last_successful_collection_at||d.at)+healthDetails)+'</span></div>'+(this.message?'<p class="feedback" role="status">'+ES(this.message)+'</p>':'')+
   this.uiFragment('controller',this.controllerPanel(d,hist))+this.uiFragment('inputs',this.inputHealth())+this.uiFragment('optimizer',this.optimizerPanel(d))+
   '<div class="metrics">'+stat('FVE · výroba '+forecastDay,NF(forecast,1),'kWh',d.active?'Uložená předpověď · '+TM(d.session?.captured_at):'Odhad solární výroby během dne')+stat('Strop stínového dobíjení',target===0?'Bez dobíjení':NF(target,0),target===0?'':'%', d.allocation_policy==='instant-max-fill-v1'?'Využít volný výkon; ekonomický cíl je poradní':plannerTarget!=null?'Podle spotřeby, FVE a scénářů':'Záložní tabulka 5 / 10 / 15 kWh')+stat('Stínový zákaz vybíjení',forbid?'Požadován':'Bez požadavku','',forecast==null?'Chybí předpověď · konzervativní návrh':forbid?'Pravidlo: předpověď pod 30 kWh':'Předpověď alespoň 30 kWh')+stat('Přívod · teoreticky za 03–05','34,50','kWh','25 A × 230 V × 3 × 2 h · účiník 1 · celý dům')+'</div>'+
   '<div class="flows"><section class="panel ev-panel"><div class="panel-title">'+ICON('car')+'<h2>Elektromobil</h2><span class="tag">SKUTEČNOST + IDEÁLNÍ ALOKACE</span></div><div class="limits"><div title="number.solax_api_max_charge_current_setting · aktualizace '+ES(TM(wallbox?.last_updated))+'"><label>Wallbox · nastavený limit</label><b>'+NF(STATE_NUMBER(wallbox),0)+' <small>A / fáze AC</small></b></div><div title="number.tesla_model_y_juniper_nabijeci_proud · aktualizace '+ES(TM(tesla?.last_updated))+'"><label>Tesla · nastavený limit</label><b>'+NF(STATE_NUMBER(tesla),0)+' <small>A / fáze AC</small></b></div></div><div class="power-pair"><div><label>'+ES(evInput?.usable?'HA údaj · v časové mezi':'Poslední HA údaj')+'</label><strong>'+KW(a.ev_w)+'</strong></div><div class="proposed"><label>'+flowLabel+'</label><strong>'+KW(s.ev_ac_w)+'</strong></div></div><div class="progress"><span style="width:'+Math.max(0,Math.min(100,Number(a.ev_soc)||0))+'%"></span></div><div class="inline"><span>SOC <b>'+NF(a.ev_soc,0)+' %</b> → cíl <b>'+NF(a.ev_target_soc,0)+' %</b></span><span>'+ES(a.ev_connected==='on'?'Kabel připojen':a.ev_connected==='off'?'Kabel odpojen':'Kabel neověřen')+'</span></div>'+(evStale?'<p class="input-bad">Wallbox: hlášení staré '+ES(AGE(evInput.age_seconds))+'. Hodnota není čerstvý vstup pro model.</p>':'')+(!input('ev_soc')?.usable||!input('ev_connected')?.usable?'<p class="foot">SOC a kabel jsou poslední známé stavy; čerstvost ověř v přehledu vstupů.</p>':'')+'<p class="foot">Modelově odloženo <b>'+energy(model,'ev_reallocated_kwh')+' kWh</b> proti naměřenému požadavku. Připravenost do 05:00 zatím nelze spolehlivě určit bez ověřeného energetického modelu auta.</p></section>'+
   '<section class="panel bat-panel"><div class="panel-title">'+ICON('battery')+'<h2>Baterie SolaX</h2><span class="tag">'+(modelSOC==null?'SKUTEČNÉ SOC':'IDEÁLNÍ MODEL SOC')+'</span></div><div class="limits"><div title="number.solax_battery_charge_max_current · aktualizace '+ES(TM(batteryLimit?.last_updated))+'"><label>Max. nabíjecí proud · nastavení</label><b>'+NF(STATE_NUMBER(batteryLimit),0)+' <small>A DC</small></b></div><div title="sensor.solax_battery_current_charge"><label>Naměřený proud baterie</label><b>'+NF(STATE_NUMBER(batteryCurrent),1)+' <small>A DC</small></b></div></div><div class="power-pair"><div><label>'+ES(batteryInput?.usable?'HA údaj · DC, + nabíjení':'Poslední HA údaj · DC')+'</label><strong>'+KW(a.battery_dc_w)+'</strong></div><div class="proposed"><label>'+flowLabel+' · AC</label><strong>'+KW(s.battery_ac_w)+'</strong></div></div><div class="progress"><span style="width:'+Math.max(0,Math.min(100,Number(modelSOC??soc)||0))+'%"></span></div><div class="inline"><span>Skutečné SOC <b>'+NF(soc,0)+' %</b></span><span>Model <b>'+NF(modelSOC,1)+' %</b> → <b>'+(target===0?'bez cíle':NF(target,0)+' %')+'</b></span></div><p class="foot">Přírůstek modelu <b>'+energy(model,'battery_kwh_ac')+' kWh AC</b>. '+(d.session?.battery_energy_model?'Převod energie/SOC vychází z pozorovaných úseků baterie; účinnost síťového nabíjení zůstává předpoklad.':'Starší relace používá katalogových 10,4 kWh a předpoklad účinnosti 90 %.')+' Model SOC není měření.</p></section></div>'+
   '<div class="analysis-grid phase-row"><section class="panel phase-panel"><div class="panel-title">'+ICON('grid')+'<h2>Přívod po fázích</h2><span class="warning-tag" title="Nově měřené proudy ověřujeme při nabíjení elektromobilu">OVĚŘUJEME PROUDY</span></div><div class="table-scroll"><table><thead><tr><th>Měření</th><th><i class="phase-dot p1"></i>L1</th><th><i class="phase-dot p2"></i>L2</th><th><i class="phase-dot p3"></i>L3</th></tr></thead><tbody>'+phaseRows+'</tbody></table></div><div class="phase-footer"><span>Dům včetně auta <b>'+KW(a.house_w)+'</b></span><span>Navržený přívod <b>'+KW(s.grid_model_w)+'</b></span><span>Omezující fáze <b>'+(s.binding_phase?'L'+s.binding_phase:'—')+'</b></span></div><details class="capacity"><summary>Kapacita přípojky a předpoklady modelu</summary><div class="table-scroll"><table><thead><tr><th>Při 230 V / fázi</th><th>Výkon celkem</th><th>Energie za 2 h</th></tr></thead><tbody><tr><th>Jistič 3×25 A · účiník 1</th><td>17,25 kW</td><td>34,50 kWh</td></tr></tbody></table></div><p class="foot">Všechny hodnoty jsou pro celý dům při rovnoměrném zatížení a stálém napětí 230 V. Pro auto a baterii zbývá energie po spotřebě domu; nerovnoměrné zatížení dostupný výkon omezí. Model používá skutečná napětí jednotlivých fází.</p><p class="foot">Proudy čteme z nových senzorů SolaX Grid Current L1–L3. Jejich shodu při nabíjení auta teprve ověřujeme. Stínová alokace používá 25 A a aktuální měření po fázích. Historický rozpočet a ekonomický cíl SOC ji nezastavují. Reakční rezerva pro fyzické řízení není ověřená; auto se odečte a nahradí návrhem právě jednou. Nastavených 30 A baterie je proud na DC straně, nikoli proud fáze přípojky.</p></details></section>'+
   '<section class="panel"><div class="panel-title"><h2>Ideální alokace obou priorit</h2><span class="tag">'+(d.active?'DNEŠNÍ RELACE':hist[0]?'NOC '+ES(hist[0].day):'ČEKÁ NA DALŠÍ NOC')+'</span></div><div class="table-scroll"><table><thead><tr><th>Za aktuální noc</th><th>Zvolená · ideální</th><th>EV první</th><th>BAT první</th></tr></thead><tbody>'+comparisons+'</tbody></table></div>'+(comparisonNote?'<p class="foot">'+ES(comparisonNote)+'</p>':'')+(comparisonWarning?'<p class="input-bad">'+ES(comparisonWarning)+'</p>':'')+'<p class="foot">Obě varianty používají stejný naměřený požadavek auta a ostatní zátěže. Odložené kWh neznamenají prokázaně nesplněný cíl při odjezdu; další dohánění model nepředpokládá. SOC modelu se během mezer nemění; nejde o předpověď koncového SOC celé noci. Změny vytápění a bojleru vyvolané starou EV prioritou se nepřepočítávají.</p></section></div>'+
   '<div class="analysis-grid"><section class="panel"><div class="panel-title chart-title"><h2>Naměřené EV a ideální alokace</h2><select id="range" aria-label="Rozsah grafu">'+[8,24,72].map(h=>'<option value="'+h+'" '+(h===this.range?'selected':'')+'>'+h+' hodin</option>').join('')+'</select></div><div class="legend"><span style="--c:#94a9bb">Auto · záznam HA</span><span style="--c:#66b9ff">Auto · ideální alokace</span><span style="--c:#5fdfbc">Baterie · ideální alokace AC</span><small>kW</small></div><div id="chart">'+this.chart()+'</div><p class="foot">Graf ukazuje zapsané stavy HA mezi změnami. Neměnná čára není důkaz nepřetržité odezvy čidla; platné pokrytí výpočtu je uvedeno zvlášť.</p></section>'+
   '<section class="panel nights-panel"><div class="panel-title"><h2>Statistiky jednotlivých nocí</h2><span class="tag">POSLEDNÍCH 14 NOCÍ</span></div>'+(nights?'<div class="table-scroll"><table><thead><tr><th>Noc</th><th>Auto měřeno · kWh</th><th>Ideální baterie · kWh AC</th><th>Regulátor · původní běh · kWh AC</th><th>Baterie při EV / BAT prioritě</th><th>Ideální SOC · platné úseky</th><th>EV odloženo · kWh</th><th>Pokrytí · min</th><th>Max A · L1 / L2 / L3</th></tr></thead><tbody>'+nights+'</tbody></table></div>':'<div class="empty"><strong>První nová relace začne nadcházející noc.</strong><span>Po 05:00 přibude souhrn obou priorit, pokrytí měření a odložené energie. Starší záznamy zůstávají zachované v koordinátoru.</span></div>')+'</section></div>'+
   this.uiFragment('journal',controlHTML)+this.uiFragment('audit',this.auditPanels(d,forecast,target))+this.uiFragment('automations',this.automationPanel(d))+
   '<footer><span>Plán SOC v2 · stínové priority · RPi4 · Europe/Prague</span><span>Provozní stav [sensor.solax_run_mode]: '+ES(a.inverter_run_mode||'neznámý')+' · volba [select.solax_charger_use_mode]: '+ES(a.inverter_mode||'neznámá')+' · baterie '+NF(a.battery_v,0)+' V / '+NF(a.battery_a,1)+' A · DC limit '+NF(a.battery_limit_a,0)+' A</span></footer></div>';
  this.updateDOM(html);
  const sourceSelect=this.shadowRoot.querySelector('#control-source');if(sourceSelect)sourceSelect.onchange=e=>{this.controlSources={...this.controlSources,[this.controlSelectedDay()]:e.target.value};this.controlShowAll=false;this.controlPage=0;this.render();this.loadControlHistory(true);};
  const cs=this.shadowRoot.querySelector('#control-day');if(cs)cs.onchange=e=>{this.controlDay=e.target.value;this.controlShowAll=false;this.controlPage=0;this.render();this.loadControlHistory(true);};
  const cr=this.shadowRoot.querySelector('#control-reload');if(cr)cr.onclick=()=>this.loadControlHistory(true);
  const journalScroll=this.shadowRoot.querySelector('#control-events');if(journalScroll)journalScroll.onscroll=()=>{this.journalScrollLeft=journalScroll.scrollLeft;};
  const ca=this.shadowRoot.querySelector('#control-all');if(ca)ca.onclick=()=>{this.controlShowAll=!this.controlShowAll;this.controlPage=0;this.controlRecentEnd=null;this.updateControlPage(true);};
  const latest=this.shadowRoot.querySelector('#control-latest');if(latest)latest.onclick=()=>{this.controlRecentEnd=null;this.updateControlPage();const n=this.shadowRoot.querySelector('#control-events');if(n)n.scrollTop=n.scrollHeight;};
  for(const [id,step]of [['control-prev',-1],['control-next',1]]){const button=this.shadowRoot.querySelector('#'+id);if(button)button.onclick=()=>{this.controlPage=Math.max(0,(this.controlPage||0)+step);this.updateControlPage(true);};}
